class Solution {
    private int gcd(int a, int b) {
        while (b != 0) {
            int t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
    public ListNode insertGreatestCommonDivisors(ListNode head) {
        ListNode curr = head;
        while (curr != null && curr.next != null) {
            int g = gcd(curr.val, curr.next.val);
            ListNode node = new ListNode(g, curr.next);
            curr.next = node;
            curr = node.next;
        }
        return head;
    }
}

