var insertGreatestCommonDivisors = function(head) {
    function gcd(a, b) {
        while (b !== 0) {
            const t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
    let curr = head;
    while (curr && curr.next) {
        const g = gcd(curr.val, curr.next.val);
        const node = new ListNode(g, curr.next);
        curr.next = node;
        curr = node.next;
    }
    return head;
};
